1	// Node API checker lane (mfs-cx/node-api-checker): port of the checker / symbol / type / signature
2	// request handlers of the tsgo API (originally based on microsoft/TypeScript b85298b6, tsc/internal/api/session.go +
3	// proto.go). See checker/README.md for the contract, id ownership and the per-method coverage inventory.
4	//
5	// Core hook (docs/NODE_API.md, "checker hook"): `handle(session, method, params)` and
6	// `CheckerSnapshotState`. Internally the handlers run against the `CheckerHost` trait so they only
7	// borrow snapshots, node handles, source-file descriptors and the AST encoder for one request;
8	// `SessionHost` adapts core's `Session` to it.
9	
10	pub mod dispatch;
11	mod handlers_ls;
12	mod handlers_symbols;
13	mod handlers_types;
