41	/// Per-snapshot checker registries (Go `snapshotData.symbolRegistry` + `projectRegistries`). Core
42	/// creates it with `Default` when a snapshot is registered and drops it with the snapshot; dropping
43	/// releases every registered pointer.
44	#[derive(Default)]
45	#[expect(
46	    clippy::too_long_first_doc_paragraph,
47	    reason = "Public for the integration tests; the comment keeps its upstream wording."
48	)]
49	pub struct CheckerSnapshotState {
50	    pub registry: Arc<CheckerRegistry>,
51	}
