59	/// Core entry point. `None` only for methods this lane does not recognize.
60	pub(crate) fn handle(
61	    session: &Session,
62	    method: &str,
63	    params: &Value,
64	) -> Option<ApiResult<Response>> {
65	    let host = SessionHost { session };
66	    let result = dispatch::handle(&host, method, params)?;
67	    Some(result.map_err(to_api_error).and_then(|response| match response {
68	        CheckerResponse::Json(value) => json_response(&value),
69	        CheckerResponse::EncodedNode(bytes) => {
70	            if session.binary_responses() {
71	                Ok(Response::Binary(bytes))
72	            } else {
73	                json_response(&Obj::new().set("data", Value::String(base64_encode(&bytes))).build())
74	            }
75	        }
76	    }))
77	}
