79	/// Go `newFileSymbolResponse`, for core handlers that return a binder symbol from an ordinary cached AST.
80	pub(crate) fn file_symbol_response(session: &Session, symbol: P<Symbol>) -> ApiResult<Value> {
81	    setup::file_symbol_response(&SessionHost { session }, symbol).map_err(to_api_error)
82	}
83	
84	fn to_api_error(e: CheckerError) -> ApiError {
85	    match e.kind {
86	        CheckerErrorKind::InvalidRequest => ApiError::invalid_request(e.message),
87	        CheckerErrorKind::Client => ApiError::client(e.message),
88	        CheckerErrorKind::Unsupported => {
89	            ApiError { kind: ErrorKind::Unsupported, message: e.message }
90	        }
91	        CheckerErrorKind::Internal => ApiError::internal(e.message),
92	    }
93	}
94	
95	fn from_api_error(e: ApiError) -> CheckerError {
96	    match e.kind {
97	        ErrorKind::InvalidRequest => CheckerError::invalid(e.message),
98	        ErrorKind::ClientError => CheckerError::client(e.message),
99	        ErrorKind::Unsupported => CheckerError::unsupported(e.message),
100	        ErrorKind::Internal => {
101	            CheckerError { kind: CheckerErrorKind::Internal, message: e.message }
102	        }
103	    }
104	}
