106	/// Adapts core's `Session` to `CheckerHost`.
107	struct SessionHost<'a> {
108	    session: &'a Session,
109	}
110	
111	impl CheckerHost for SessionHost<'_> {
112	    fn context(&self) -> Context {
113	        Context::background()
114	    }
115	
116	    fn snapshot(&self, handle: u64) -> CheckerResult<SnapshotScope> {
117	        let sd = self.session.snapshot_data(handle).map_err(from_api_error)?;
118	        let snapshot = Arc::clone(&sd.snapshot);
119	        let registry = Arc::clone(&sd.checker_state.registry);
120	        // The scope pins `SnapshotData` (and with it the project snapshot) until the request ends.
121	        Ok(SnapshotScope { handle, snapshot, registry, release: Some(Box::new(move || drop(sd))) })
122	    }
123	
124	    fn acquire_cached_source_file(&self, descriptor: &Value) -> CheckerResult<CachedFileScope> {
125	        let lease = self.session.acquire_cached_source_file(descriptor).map_err(from_api_error)?;
126	        Ok(CachedFileScope {
127	            file: lease.source_file(),
128	            release: Some(Box::new(move || lease.release())),
129	        })
130	    }
131	
132	    fn source_file_descriptor(&self, file: P<SourceFile>) -> CheckerResult<Value> {
133	        Ok(crate::sourcefiles::source_file_descriptor(file))
134	    }
135	
136	    fn source_file_descriptor_matches(
137	        &self,
138	        file: P<SourceFile>,
139	        descriptor: &Value,
140	    ) -> CheckerResult<bool> {
141	        Ok(crate::sourcefiles::source_file_descriptor_matches(file, descriptor))
142	    }
143	
144	    fn source_file_node_id(&self, file: P<SourceFile>) -> CheckerResult<u64> {
145	        Ok(crate::sourcefiles::source_file_node_id(file))
146	    }
147	
148	    fn node_handle(&self, node: P<Node>) -> CheckerResult<String> {
149	        self.session.node_handle_from(node).map_err(from_api_error)
150	    }
151	
152	    fn resolve_node_handle(
153	        &self,
154	        program: &'static Program,
155	        handle: &str,
156	    ) -> CheckerResult<P<Node>> {
157	        self.session.resolve_node_handle(program, handle).map_err(from_api_error)
158	    }
159	
160	    fn encode_node(&self, node: P<Node>) -> CheckerResult<Vec<u8>> {
161	        Session::encode_node(node).map_err(from_api_error)
162	    }
163	
164	    fn clone_snapshot_with_auto_imports(
165	        &self,
166	        base: &Snapshot,
167	        file_name: &str,
168	    ) -> CheckerResult<Arc<Snapshot>> {
169	        let file_name = tsrs_core::tspath::get_normalized_absolute_path(
170	            file_name,
171	            self.session.current_directory(),
172	        );
173	        let uri = tsrs_ls::lsconv::file_name_to_document_uri(&file_name);
174	        Ok(self.session.snapshot_host.clone_snapshot_with_auto_imports(
175	            &self.context(),
176	            base,
177	            &uri,
178	            None,
179	        ))
180	    }
181	
182	    fn try_adopt_snapshot_in_background(&self, base: &Arc<Snapshot>, prepared: &Arc<Snapshot>) {
183	        if let Some(project_session) = &self.session.project_session {
184	            project_session
185	                .try_adopt_snapshot_in_background(Arc::clone(base), Arc::clone(prepared));
186	        }
187	    }
188	}
189	
190	/// Standard base64 with padding (Go `base64.StdEncoding`).
191	pub fn base64_encode(data: &[u8]) -> String {
192	    const ALPHABET: &[u8; 64] = b"REDACTED";
193	    let mut out = String::with_capacity(data.len().div_ceil(3) * 4);
194	    out.extend(data.chunks(3).flat_map(|chunk| {
195	        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
196	        let n = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | b[2] as u32;
197	        [
198	            ALPHABET[((n >> 18) & 63) as usize] as char,
199	            ALPHABET[((n >> 12) & 63) as usize] as char,
200	            if chunk.len() > 1 { ALPHABET[((n >> 6) & 63) as usize] as char } else { '=' },
201	            if chunk.len() > 2 { ALPHABET[(n & 63) as usize] as char } else { '=' },
202	        ]
203	    }));
204	    out
205	}
