1108	    /// Stands in for a session: makes snapshot 1 of as many programs as asked on `createSnapshot` (so a run that asked
1109	    /// all the lanes' programs of one snapshot would open), and fails or panics on `updateSnapshot`, which
1110	    /// derives each other lane's; records the snapshots it was told to release, and whether it was closed.
1111	    struct Underived {
1112	        panics: bool,
1113	        released: Arc<Mutex<Vec<u64>>>,
1114	        closed: Arc<std::sync::atomic::AtomicBool>,
1115	    }
1116	
1117	    impl Served for Underived {
1118	        fn handle(&self, method: &str, params: &[u8]) -> Result<String, Failure> {
1119	            match method {
1120	                "initialize" => Ok("null".to_string()),
1121	                "createSnapshot" => {
1122	                    // As many programs as asked for.
1123	                    let params: Value = serde_json::from_slice(params).unwrap();
1124	                    let count = params["createPrograms"].as_array().map_or(1, Vec::len);
1125	                    let projects: Vec<Value> = (0..count).map(|n| json!({ "id": format!("p{n}") })).collect();
1126	                    Ok(json!({ "snapshot": 1, "projects": projects }).to_string())
1127	                }
1128	                "updateSnapshot" if self.panics => panic!("checker invariant broken"),
1129	                "updateSnapshot" => Err(Failure { message: "a file nests too deep".to_string(), panicked: false }),
1130	                "release" => {
1131	                    let params: Value = serde_json::from_slice(params).unwrap();
1132	                    self.released.lock().unwrap().push(params["snapshot"].as_u64().unwrap());
1133	                    Ok("null".to_string())
1134	                }
1135	                other => panic!("unexpected {other}"),
1136	            }
1137	        }
1138	
1139	        fn discard(&self, _method: &str, _answer: &str) {}
1140	
1141	        fn close(&self) {
1142	            self.closed.store(true, std::sync::atomic::Ordering::Release);
1143	        }
1144	    }
