1146	    /// A lane whose snapshot cannot be made fails the opening, and the snapshot made before it is released, since no
1147	    /// one will hold it; one that panics stops the checker, which closes its session and every snapshot with it.
1148	    #[test]
1149	    fn a_lane_whose_snapshot_cannot_be_made_releases_the_one_made_before_it() {
1150	        for panics in [false, true] {
1151	            let released = Arc::new(Mutex::new(Vec::new()));
1152	            let closed = Arc::new(std::sync::atomic::AtomicBool::new(false));
1153	            let session = Underived { panics, released: released.clone(), closed: closed.clone() };
1154	            let checker = Backend::spawn(2, move || session).unwrap();
1155	            let runtime = multi_thread();
1156	
1157	            let opened = runtime.block_on(Rpc::open_programs(
1158	                checker.client(),
1159	                Duration::from_secs(5),
1160	                None,
1161	                &["/p/a.ts".to_string()],
1162	                false,
1163	                2,
1164	            ));
1165	
1166	            assert!(opened.is_err(), "panics: {panics}");
1167	            runtime.block_on(checker.shutdown_within(Duration::from_secs(5)));
1168	            if panics {
1169	                assert!(closed.load(std::sync::atomic::Ordering::Acquire), "the session is closed");
1170	            } else {
1171	                assert_eq!(*released.lock().unwrap(), [1], "the first lane's snapshot is released");
1172	            }
1173	        }
1174	    }
