1	//! Typed calls over one session of the linked checker ([`crate::checker`]). Wire shapes are the ones the official 7.1
2	//! client sends (traced against `7.1.0-beta`); a method this module does not name is not used.
3	
4	use std::collections::BTreeMap;
5	use std::sync::{Arc, Mutex};
6	use std::time::Duration;
7	
8	use serde::de::DeserializeOwned;
9	use serde::{Deserialize, Serialize};
10	use serde_json::value::RawValue;
11	use serde_json::{Value, json};
12	
13	use crate::checker::{Client, RequestError};
14	
15	/// Why a call failed, split by whether the rest of the run can go on.
16	#[derive(Debug)]
17	pub(crate) enum CallError {
18	    /// The session is gone or stuck: every later call would fail the same way.
19	    Fatal(String),
20	    /// The checker rejected this one call; other components may still resolve.
21	    Rejected(String),
22	    /// The run's heap is past its budget ([`crate::heap`]): the call was not sent, and no later one will be.
23	    OverBudget,
24	}
25	
26	impl std::fmt::Display for CallError {
27	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
28	        match self {
29	            CallError::Fatal(message) | CallError::Rejected(message) => f.write_str(message),
