265	    lanes: Arc<[mpsc::Sender<Job>]>,
266	    lane: usize,
267	    /// The session, asked in place, when this client was given to work on its lane's thread.
268	    in_place: Option<Arc<dyn Ask>>,
269	}
270	
271	impl Client {
272	    /// The client whose requests the `lane`th thread of the checker answers ([`Backend::start`]).
273	    pub(crate) fn lane(&self, lane: usize) -> Client {
274	        Client { lanes: self.lanes.clone(), lane, in_place: None }
275	    }
276	
277	    /// Runs `work` on the thread of this client's lane, after the requests queued before it, and returns what it
278	    /// returns. The client `work` is given asks the session in place from that thread, with no channel between: a
279	    /// request costs no thread hop either way. The wait is bounded as each of its requests would be: past `deadline`
280	    /// inside one request (or before the work starts), this stops waiting with a timeout, and the work's later requests
281	    /// fail. A panic in the session ends the lane as one in a queued request does; a panic in `work` itself leaves the
282	    /// session answering, and the wait ends as from a stopped checker.
283	    pub(crate) async fn run_on_thread<T: Send + 'static>(
284	        &self,
285	        deadline: Duration,
286	        work: impl FnOnce(Client) -> T + Send + 'static,
287	    ) -> Result<T, RequestError> {
288	        let progress =
289	            Arc::new(Progress { since: Mutex::new(Some((Instant::now(), "run"))), cancelled: AtomicBool::new(false) });
290	        let abandon = Abandon(progress.clone());
291	        let (reply, mut answer) = oneshot::channel();
292	        let (lanes, lane) = (self.lanes.clone(), self.lane);
293	        let work: Box<dyn FnOnce(Arc<dyn Ask>) + Send> = Box::new(move |in_place| {
294	            let client = Client { lanes, lane, in_place: Some(in_place) };
295	            reply.send(work(client)).ok();
296	        });
297	        let Some(jobs) = self.lanes.get(self.lane % self.lanes.len().max(1)) else {
298	            return Err(RequestError::Closed);
299	        };
300	        if jobs.send(Job::Run(Run { work, progress: progress.clone() })).is_err() {
301	            return Err(RequestError::Closed);
302	        }
303	        loop {
304	            // Until the request in progress (or the wait for the work to start) is past its deadline.
305	            let wait = progress.since().map_or(deadline, |(since, _)| deadline.saturating_sub(since.elapsed()));
306	            match tokio::time::timeout(wait, &mut answer).await {
307	                Ok(Ok(done)) => {
308	                    drop(abandon);
309	                    return Ok(done);
310	                }
311	                Ok(Err(_dropped)) => return Err(RequestError::Closed),
312	                Err(_elapsed) => {
313	                    if let Some((since, method)) = progress.since()
314	                        && since.elapsed() >= deadline
315	                    {
316	                        return Err(RequestError::Timeout { method: method.to_string(), after: deadline });
317	                    }
318	                }
319	            }
320	        }
321	    }
322	
323	    /// One request, its parameters the JSON text `params`, its answer the `result` as the JSON text it arrived as. The
324	    /// wait is bounded by `deadline`.
325	    pub(crate) async fn request_raw(
326	        &self,
327	        method: &'static str,
328	        params: Vec<u8>,
329	        deadline: Duration,
330	    ) -> Result<Box<RawValue>, RequestError> {
331	        if let Some(in_place) =
332	            self.in_place.as_ref().filter(|in_place| in_place.thread() == std::thread::current().id())
333	        {
334	            let text = in_place.ask(method, &params)?;
335	            return RawValue::from_string(text)
336	                .map_err(|_invalid| RequestError::Malformed(format!("{method} answered with text that is not JSON")));
337	        }
338	        let (reply, answer) = oneshot::channel();
339	        let asked = Asked { method, params, reply };
340	        let Some(jobs) = self.lanes.get(self.lane % self.lanes.len().max(1)) else {
341	            return Err(RequestError::Closed);
342	        };
343	        if jobs.send(Job::Request(asked)).is_err() {
344	            return Err(RequestError::Closed);
345	        }
346	        let answered = match tokio::time::timeout(deadline, answer).await {
347	            Ok(Ok(answered)) => answered,
348	            // The thread ended without answering: stopped, or its session could not be created.
349	            Ok(Err(_dropped)) => return Err(RequestError::Closed),
350	            Err(_elapsed) => return Err(RequestError::Timeout { method: method.to_string(), after: deadline }),
351	        };
352	        match answered {
353	            Ok(text) => RawValue::from_string(text)
354	                .map_err(|_invalid| RequestError::Malformed(format!("{method} answered with text that is not JSON"))),
355	            Err(message) => Err(RequestError::Rejected(message)),
356	        }
357	    }
358	
359	    fn stop(&self) {
360	        // A thread that already ended has nothing to stop.
361	        for jobs in self.lanes.iter() {
362	            jobs.send(Job::Stop).ok();
363	        }
364	    }
365	}
