367	/// Why the checker did not answer a request.
368	pub(crate) struct Failure {
369	    pub(crate) message: String,
370	    /// A panic unwound through the session, which is not asked again.
371	    pub(crate) panicked: bool,
372	}
373	
374	/// What the checker thread asks: the `tsrs` session, or a stand-in in the tests.
375	pub(crate) trait Served {
376	    /// Answers one request with its JSON text.
377	    fn handle(&self, method: &str, params: &[u8]) -> Result<String, Failure>;
378	    /// Releases the snapshot an answer of `method` made, when that answer will not reach the caller, who could then
379	    /// never release it.
380	    fn discard(&self, method: &str, answer: &str);
381	    fn close(&self);
382	}
383	
384	/// The snapshot an answer of `method` made: `createSnapshot` and `updateSnapshot` each make one, which lives until it
385	/// is released.
386	fn snapshot_made(method: &str, answer: &str) -> Option<u64> {
387	    if !matches!(method, "createSnapshot" | "updateSnapshot") {
388	        return None;
389	    }
390	    serde_json::from_str::<Value>(answer).ok()?.get("snapshot")?.as_u64()
391	}
392	
393	/// A `tsrs` session over the disk, where every file is measured before the session reads it.
394	struct TsrsSession {
395	    session: Arc<Session>,
396	    /// The files nested past [`MAX_NESTING`] the session was refused, with their depth (see [`TsrsSession::answer`]).
397	    refused: Arc<Mutex<Vec<(String, usize)>>>,
398	    /// Held alone by a request that builds a snapshot, and shared by every other, across the lanes.
399	    building: RwLock<()>,
400	}
401	
402	impl TsrsSession {
403	    /// With `reads`, every question the session asks of the disk is noted there ([`crate::kept`]) with the answer the
404	    /// session got; a file refused for its nesting also spoils the notes, so a run that met one keeps no answer.
405	    fn open(cwd: String, reads: Option<Arc<Reads>>) -> TsrsSession {
406	        let refused: Arc<Mutex<Vec<(String, usize)>>> = Arc::default();
407	        let noted = Arc::clone(&refused);
408	        let spoiled = reads.clone();
409	        let measured = wrapvfs::wrap(
410	            osvfs::fs(),
411	            wrapvfs::Replacements {
412	                read_file: Some(Box::new(move |path: &str| {
413	                    let text = osvfs::fs().read_file(path)?;
414	                    let depth = nesting(&text);
415	                    if depth <= MAX_NESTING {
416	                        return Some(text);
417	                    }
418	                    noted.lock().unwrap_or_else(std::sync::PoisonError::into_inner).push((path.to_string(), depth));
419	                    if let Some(reads) = &spoiled {
420	                        reads.spoil();
421	                    }
422	                    None
423	                })),
424	                ..wrapvfs::Replacements::default()
425	            },
426	        );
427	        // Noted outside the measuring, so each question is noted as the session saw it answered: a refused file as
428	        // absent, which the disk does not answer again.
429	        let fs: Arc<dyn FS> = match reads {
430	            Some(reads) => Arc::new(bundled::wrap_fs(Recording { inner: measured, reads })),
431	            None => Arc::new(bundled::wrap_fs(measured)),
432	        };
433	        let session = Session::new(SessionOptions::new(cwd, bundled::lib_path(), fs, false));
434	        TsrsSession { session, refused, building: RwLock::new(()) }
435	    }
436	
437	    fn refused(&self) -> std::sync::MutexGuard<'_, Vec<(String, usize)>> {
438	        self.refused.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
439	    }
440	
441	    /// Answers one request and the refusals it met. A request that builds a snapshot (the ones that read files) has
442	    /// the session to itself among the lanes, so a refusal noted meanwhile is its own; it clears the list before and
443	    /// takes it after. Any other request runs beside the others and only looks: a refusal one of them met (a file read
444	    /// late) fails every request that sees it, until the next snapshot is built.
445	    fn answer(&self, method: &str, params: &[u8]) -> (tsrs_api::ApiResult<Response>, Option<(String, usize)>) {
446	        if matches!(method, "createSnapshot" | "updateSnapshot") {
447	            let _alone = self.building.write().unwrap_or_else(std::sync::PoisonError::into_inner);
448	            self.refused().clear();
449	            let answered = self.session.handle_request(method, params);
450	            let refused = std::mem::take(&mut *self.refused()).into_iter().next();
451	            (answered, refused)
452	        } else {
453	            let _beside = self.building.read().unwrap_or_else(std::sync::PoisonError::into_inner);
454	            let answered = self.session.handle_request(method, params);
455	            let refused = self.refused().first().cloned();
456	            (answered, refused)
457	        }
458	    }
459	}
460	
461	impl Served for TsrsSession {
462	    fn handle(&self, method: &str, params: &[u8]) -> Result<String, Failure> {
463	        let (answered, refused) = self.answer(method, params);
464	        if let Some((file, depth)) = refused {
465	            // The session answered without the file, which it took for missing: not an answer to give, and a snapshot
466	            // it made for it would be held with no one to release it.
467	            if let Ok(Response::Json(text)) = &answered {
468	                self.discard(method, text);
469	            }
470	            let message = format!(
471	                "{file} nests brackets {depth} deep, more than the {MAX_NESTING} the built-in checker reads without \
472	                 risking a stack overflow; its components keep their structural answer"
473	            );
474	            return Err(Failure { message, panicked: false });
475	        }
476	        match answered {
477	            Ok(Response::Json(text)) => Ok(text),
478	            Ok(Response::Binary(_)) => {
479	                Err(Failure { message: format!("{method} answered in binary, not JSON"), panicked: false })
480	            }
481	            Err(error) => {
482	                let message = error.to_string();
483	                // `tsrs_api` catches a panic in a handler and reports it as an internal error that says so.
484	                let panicked = error.kind == ErrorKind::Internal && message.starts_with("panic: ");
485	                Err(Failure { message, panicked })
486	            }
487	        }
488	    }
489	
490	    fn discard(&self, method: &str, answer: &str) {
491	        if let Some(snapshot) = snapshot_made(method, answer) {
492	            let params = serde_json::json!({ "snapshot": snapshot }).to_string();
493	            if let Err(error) = self.session.handle_request("release", params.as_bytes()) {
494	                tracing::debug!(snapshot, %error, "could not release the snapshot of an answer nobody receives");
495	            }
496	        }
497	    }
498	
499	    fn close(&self) {
500	        self.session.close();
501	    }
502	}
503	
504	/// The checker threads: one session, each thread answering the requests of its queue (its lane) in turn. The first
505	/// thread creates the session and starts the others.
506	fn serve<S: Served + Send + Sync + 'static>(
507	    open: impl FnOnce() -> S,
508	    queues: Vec<mpsc::Receiver<Job>>,
509	    ended: Arc<AtomicBool>,
510	    closing: mpsc::Sender<()>,
511	) {
512	    let session = Arc::new(open());
513	    let left = Arc::new(AtomicUsize::new(queues.len()));
514	    let mut queues = queues.into_iter();
515	    let Some(own) = queues.next() else {
516	        catch_unwind(AssertUnwindSafe(|| session.close())).ok();
517	        return;
518	    };
519	    for (index, queue) in queues.enumerate() {
520	        let lane =
521	            Lane { session: session.clone(), ended: ended.clone(), left: left.clone(), _closing: closing.clone() };
522	        let spawned = std::thread::Builder::new()
523	            .name(format!("caliper-checker-{}", index + 1))
524	            .stack_size(CHECKER_STACK_BYTES)
525	            .spawn(move || lane.answer(&queue));
526	        // Its queue is dropped with the closure, so its lane's requests fail as from a stopped checker.
527	        if spawned.is_err() {
528	            left.fetch_sub(1, Ordering::AcqRel);
529	        }
530	    }
531	    Lane { session, ended, left, _closing: closing }.answer(&own);
532	}
533	
534	/// The message of a request a lane refuses because a panic unwound through the session.
535	const STOPPED: &str = "the built-in checker stopped: a panic unwound through its session";
536	
537	/// One request to the session, a panic caught as a failure that says so.
538	fn handled<S: Served>(session: &S, method: &'static str, params: &[u8]) -> Result<String, Failure> {
539	    catch_unwind(AssertUnwindSafe(|| session.handle(method, params))).unwrap_or_else(|panic| {
540	        let text = panic
541	            .downcast_ref::<String>()
542	            .map(String::as_str)
543	            .or_else(|| panic.downcast_ref::<&str>().copied())
544	            .unwrap_or("a panic with no message");
545	        Err(Failure { message: format!("panic: {text}"), panicked: true })
546	    })
547	}
548	
549	/// The session as work on a lane's thread asks it ([`Client::run_on_thread`]).
550	struct InPlace<S> {
551	    session: Arc<S>,
552	    ended: Arc<AtomicBool>,
553	    progress: Arc<Progress>,
554	    thread: ThreadId,
555	    /// Set when this lane is to leave: a panic unwound through the session. Requests after it fail as to a stopped
556	    /// checker, as they would once the lane's thread had ended.
557	    left: AtomicBool,
558	}
559	
560	impl<S: Served + Send + Sync> Ask for InPlace<S> {

