        let text = r#"[{"reference":{"kind":1,"id":4,"file":{"fileName":"/a.ts","nodeId":"7"}},"name":"___size","flags":4,"declarations":["1.2./a.ts"],"parent":{"id":9,"file":"7"}}]"#;
